import{_ as t,c as s,o as r,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"《周易集註》簡介","description":"周易集註 - 《周易集註》簡介","frontmatter":{"title":"《周易集註》簡介","description":"周易集註 - 《周易集註》簡介"},"headers":[],"relativePath":"classics/jizhu/001.md","filePath":"classics/jizhu/001.md"}'),n={name:"classics/jizhu/001.md"};function i(c,a,o,d,p,u){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《周易集註》簡介",tabindex:"-1"},[l("《周易集註》簡介 "),e("a",{class:"header-anchor",href:"#《周易集註》簡介","aria-label":"Permalink to “《周易集註》簡介”"},"​")],-1),e("p",null,"《周易集註》是明代學者來知德所著的一部易學著作。該書共16卷，繼承並發展了朱熹的理數之學，對《周易》的象數進行了深入研究和闡釋。來知德在書中側重於取《繫辭》中的“錯綜其數”來論象，以象數來闡釋義理，再以義理來印證象數，縱橫推演，為學易者提供了深入理解《周易》的新視角。",-1),e("p",null,"來知德（1525—1604），字矣鮮，別號瞿唐，是明代著名的理學家和易學家。他的《周易集註》用功尤深，成為易學研究的重要著作，亦稱來氏易學。鄭同，作為易學學者和北京學易齋的創辦人，對《周易集註》進行了整理。",-1),e("p",null,"《周易集註》在明清兩代流傳甚廣，對後世的易學研究產生了深遠的影響。書中的註解先釋象義、字義及錯綜義，然後訓本卦本爻正意，參互旁通，自成一說。通過該書，讀者可以對《周易》所用的“錯”“綜”等闡釋方法有更深入的理解。",-1),e("p",null,"此外，來知德在《周易集註》中對《周易》中的卦象、爻辭和象文進行了詳細的分析，闡述了其中的哲學思想和世界觀。這部作品不僅體現了作者深厚的易學功底，也為後來的易學研究提供了寶貴的參考和啟示。",-1)])])}const f=t(n,[["render",i]]);export{_ as __pageData,f as default};
